const wait = (ms, value) => new Promise(r => setTimeout(() => r(value), ms));

async function getTotal(cartId) {
  if (cartId < 0) throw new Error("bad cart id");   // rejects the returned promise
  const items = await wait(10, [12, 30]);           // pauses only this function
  const tax = await wait(10, 0.1);
  return items.reduce((a, b) => a + b, 0) * (1 + tax);
}

async function main() {
  try {
    const total = await getTotal(7);
    console.log("total:", total.toFixed(2));   // total: 46.20
    await getTotal(-1);
    console.log("not reached");
  } catch (err) {
    console.log("error:", err.message);        // error: bad cart id
  } finally {
    console.log("finished");                   // finished
  }
}

main();
console.log("main started");   // logs first: main is paused at its first await

