async function getJSON(url, options = {}) {
  const res = await fetch(url, options);       // rejects only on network failure
  if (!res.ok) {
    throw new Error(`HTTP ${res.status} for ${url}`);   // 404 and 500 land here
  }
  return res.json();                           // a promise: callers await it
}

async function createTodo(title) {
  return getJSON("/api/todos", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ title, done: false }),
    signal: AbortSignal.timeout(5000),         // give up after 5 seconds
  });
}

async function main() {
  try {
    const user = await getJSON("/api/users/1");
    console.log(user.name);
    await createTodo("write tests");
  } catch (err) {
    console.log("request failed:", err.message);
  }
}

